insert into public.products(odoo_product_id,external_code,code,name,commercial_unit,family_id,commercial_line_id,product_type_id,visibility,is_active,source_synced_at)
select s.odoo_product_id,s.external_code,s.code,s.name,s.commercial_unit,f.id,l.id,t.id,'hidden',s.is_active,'2026-09-17T00:00:00Z' from source s join public.product_families f on f.code=s.family_code join public.commercial_lines l on l.code=s.line_code join public.product_types t on t.code=s.type_code
on conflict(code) do update set external_code=excluded.external_code,name=excluded.name,commercial_unit=excluded.commercial_unit,family_id=excluded.family_id,commercial_line_id=excluded.commercial_line_id,product_type_id=excluded.product_type_id,is_active=excluded.is_active,source_synced_at=excluded.source_synced_at;
